import { useEffect, useMemo, useRef, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { AuthPrompt } from "@/components/AuthPrompt";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { trpc } from "@/lib/trpc";
import { timelineDecisionEvidence } from "@/lib/timelineDecisionEvidence";
import { CheckCheck, ChevronLeft, ChevronRight, CircleCheckBig, Clapperboard, FileText, GitCommitHorizontal, ImageIcon, Images, Maximize2, Minus, MonitorPlay, Pause, Play, Plus, RefreshCw, ShieldAlert, Sparkles, TriangleAlert, Volume2, ZoomIn } from "lucide-react";
import { toast } from "sonner";
import { useLocation } from "wouter";

type ProjectSummary = { id: number; name: string; audioDurationMs: number | null; sourceImageCount: number; sourcesAttached: boolean; analysisBlocker: string | null };
type ReplaceTarget = { id: number; imageFilename: string | null; startMs: number; endMs: number };
type EditorSegment = { id: number; startMs: number; endMs: number; thumbnailUrl: string | null; imageFilename: string | null; narrationText: string; selectionReason: string; decisionType: "KEEP" | "CHANGE" | "SKIP" | "FALLBACK" };
type VisualSettings = { enabled: boolean; amountPercent: number; direction: "IN" | "OUT" | "AUTO"; crossfadeDurationMs: number };
const transitionChoices = ["None", "Crossfade", "Fade to black", "Wipe left", "Wipe right", "Slide left", "Slide right", "Circle open"] as const;
type TransitionChoice = typeof transitionChoices[number];

export default function Timeline() {
  const { isAuthenticated } = useAuth();
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const projects = trpc.project.list.useQuery(undefined, { enabled: isAuthenticated });
  const [projectId, setProjectId] = useState(() => new URLSearchParams(window.location.search).get("project") ?? "");
  const [replaceTarget, setReplaceTarget] = useState<ReplaceTarget | null>(null);
  const [selectedCandidateId, setSelectedCandidateId] = useState<number | null>(null);

  useEffect(() => {
    if (!projectId && projects.data?.length) {
      const selected = projects.data.find(project => project.sourcesAttached);
      if (selected) setProjectId(String(selected.id));
    }
  }, [projectId, projects.data]);
  useEffect(() => setReplaceTarget(null), [projectId]);

  const numericProjectId = Number(projectId);
  const hasValidProjectId = Number.isInteger(numericProjectId) && numericProjectId > 0;
  const input = useMemo(() => ({ projectId: numericProjectId }), [numericProjectId]);
  const review = trpc.timeline.review.useQuery(input, { enabled: hasValidProjectId, retry: false });
  const candidates = trpc.timeline.candidates.useQuery(input, { enabled: hasValidProjectId && Boolean(replaceTarget), retry: false });
  const approve = trpc.timeline.approve.useMutation({
    onSuccess: async () => { await utils.timeline.review.invalidate(input); toast.success("Timeline approved. Native FFmpeg handoff is now unlocked."); },
    onError: error => toast.error(error.message),
  });
  const replace = trpc.timeline.substituteImage.useMutation({
    onSuccess: async () => { await Promise.all([utils.timeline.review.invalidate(input), utils.timeline.candidates.invalidate(input), utils.worker.renderHandoff.invalidate(input)]); setReplaceTarget(null); setSelectedCandidateId(null); toast.success("Image replaced. Timeline approval was revoked; review and approve again before rendering."); },
    onError: error => toast.error(error.message),
  });
  const adjustBoundary = trpc.timeline.adjustBoundary.useMutation({
    onSuccess: async () => { await Promise.all([utils.timeline.review.invalidate(input), utils.worker.renderHandoff.invalidate(input)]); toast.success("Clip timing updated. Approve the Timeline again before rendering."); },
    onError: error => toast.error(error.message),
  });
  const moveVisual = trpc.timeline.moveVisual.useMutation({
    onSuccess: async () => { await Promise.all([utils.timeline.review.invalidate(input), utils.worker.renderHandoff.invalidate(input)]); toast.success("Visual moved. Approve the Timeline again before rendering."); },
    onError: error => toast.error(error.message),
  });

  const selectedProject = projects.data?.find(project => project.id === numericProjectId) as ProjectSummary | undefined;
  const approved = review.data?.approval.status === "approved";
  const selectedCandidate = candidates.data?.find(candidate => candidate.id === selectedCandidateId) ?? null;
  const openReplaceDialog = (segment: ReplaceTarget) => { setSelectedCandidateId(null); setReplaceTarget(segment); };
  const confirmReplacement = () => { if (replaceTarget && selectedCandidate) replace.mutate({ projectId: input.projectId, segmentId: replaceTarget.id, newImageAssetId: selectedCandidate.id }); };

  if (!isAuthenticated) return <div className="mx-auto max-w-6xl"><TimelineTopbar projectId={projectId} projects={[]} onChange={() => undefined} /><AuthPrompt noun="timeline editor" /></div>;
  return <div className="mx-auto max-w-[1500px] space-y-4">
    <TimelineTopbar projectId={projectId} projects={projects.data ?? []} onChange={setProjectId} />
    {review.error ? <ReviewError message={review.error.message} /> : review.data?.segments.length ? <IntegratedTimeline narrationUrl={review.data.narrationUrl} segments={review.data.segments} projectName={review.data.project.name} visualSettings={{ enabled: review.data.project.zoomEnabled, amountPercent: review.data.project.zoomAmountPercent, direction: review.data.project.zoomDirection, crossfadeDurationMs: review.data.project.crossfadeDurationMs }} approved={approved} approving={approve.isPending} savingTiming={adjustBoundary.isPending || moveVisual.isPending} onApprove={() => approve.mutate(input)} onReplace={openReplaceDialog} onAdjustBoundary={change => adjustBoundary.mutate({ projectId: input.projectId, ...change })} onMoveVisual={(sourceSegmentId, targetSegmentId) => moveVisual.mutate({ projectId: input.projectId, sourceSegmentId, targetSegmentId })} /> : review.isLoading ? <div className="h-[620px] animate-pulse rounded-2xl border border-white/[0.07] bg-white/[0.025]" /> : <EmptyReview project={selectedProject} onOpenProjects={() => setLocation("/projects")} onOpenProviders={() => setLocation("/gemini")} />}
    <CandidateDialog target={replaceTarget} candidates={candidates.data ?? []} loading={candidates.isLoading} selectedCandidateId={selectedCandidateId} pending={replace.isPending} onClose={() => { if (!replace.isPending) setReplaceTarget(null); }} onSelect={setSelectedCandidateId} onConfirm={confirmReplacement} />
  </div>;
}

function TimelineTopbar({ projectId, projects, onChange }: { projectId: string; projects: ProjectSummary[]; onChange: (value: string) => void }) {
  const active = projects.find(project => String(project.id) === projectId);
  return <section className="overflow-hidden rounded-2xl border border-white/[0.08] bg-[#0a101b] shadow-[0_18px_50px_rgba(0,0,0,.22)]"><div className="flex flex-col gap-3 px-4 py-3 md:flex-row md:items-center md:justify-between"><div className="flex min-w-0 items-center gap-3"><span className="h-2 w-2 shrink-0 rounded-full bg-amber-300 shadow-[0_0_10px_rgba(251,191,36,.65)]" /><div className="min-w-0"><p className="truncate text-sm font-bold tracking-tight text-slate-100">VisualSync <span className="text-cyan-200">Timeline Editor</span></p><p className="mt-0.5 text-[10px] font-medium uppercase tracking-[.16em] text-slate-500">Narration + visual sequence</p></div></div><div className="flex min-w-0 flex-wrap items-center gap-2"><select value={projectId} onChange={event => onChange(event.target.value)} className="h-9 max-w-[250px] rounded-lg border border-white/[0.1] bg-[#111a28] px-3 text-xs font-medium text-slate-200 outline-none ring-0 focus:border-cyan-200/60"><option value="" disabled>Select project</option>{projects.map(project => <option key={project.id} value={String(project.id)} className="bg-[#111a28]">{project.name}</option>)}</select>{active ? <><Badge className="border border-emerald-200/15 bg-emerald-200/[0.08] text-emerald-100 hover:bg-emerald-200/[0.08]"><CheckCheck className="mr-1.5 h-3.5 w-3.5" />{active.sourceImageCount} images</Badge><Badge className="border border-white/[0.08] bg-white/[0.04] text-slate-300 hover:bg-white/[0.04]"><Volume2 className="mr-1.5 h-3.5 w-3.5 text-cyan-200" />{active.audioDurationMs ? formatTime(active.audioDurationMs) : "Narration"}</Badge></> : null}</div></div></section>;
}

function IntegratedTimeline({ narrationUrl, segments, projectName, visualSettings, approved, approving, savingTiming, onApprove, onReplace, onAdjustBoundary, onMoveVisual }: { narrationUrl: string | null; segments: EditorSegment[]; projectName: string; visualSettings: VisualSettings; approved: boolean; approving: boolean; savingTiming: boolean; onApprove: () => void; onReplace: (segment: ReplaceTarget) => void; onAdjustBoundary: (change: { segmentId: number; edge: "start" | "end"; boundaryMs: number }) => void; onMoveVisual: (sourceSegmentId: number, targetSegmentId: number) => void }) {
  const audio = useRef<HTMLAudioElement>(null); const [time, setTime] = useState(0); const [playing, setPlaying] = useState(false); const [zoom, setZoom] = useState(1); const [pan, setPan] = useState(0); const [selectedId, setSelectedId] = useState(segments[0]?.id ?? 0); const [draggedId, setDraggedId] = useState<number | null>(null); const [choice, setChoice] = useState<TransitionChoice>(visualSettings.crossfadeDurationMs > 0 ? "Crossfade" : "None"); const [gesture, setGesture] = useState<{ id: number; edge: "start" | "end"; clientX: number; original: number } | null>(null); const [draft, setDraft] = useState<number | null>(null);
  const durationMs = Math.max(1, segments.at(-1)?.endMs ?? 1); const durationSeconds = durationMs / 1000; const pps = 18 * zoom; const trackWidth = Math.max(900, durationSeconds * pps); const maxPan = Math.max(0, trackWidth - 1060); const display = useMemo(() => previewBoundaryAdjustment(segments, gesture?.id ?? null, gesture?.edge ?? null, draft), [segments, gesture, draft]); const clipIndex = Math.max(0, display.findIndex(segment => time * 1000 >= segment.startMs && time * 1000 < segment.endMs)); const current = display[clipIndex] ?? display.at(-1); const selected = display.find(segment => segment.id === selectedId) ?? current; const renderTransition = visualSettings.crossfadeDurationMs > 0 ? "Crossfade" : "None"; const playhead = Math.max(0, Math.min(trackWidth, time * pps)); const ticks = useMemo(() => buildRulerTicks(durationMs), [durationMs]);
  useEffect(() => { setSelectedId(segments[0]?.id ?? 0); setTime(0); setPan(0); setGesture(null); setDraft(null); }, [segments]);
  useEffect(() => { if (playing) setPan(value => playhead - value > 840 ? Math.min(maxPan, Math.max(0, playhead - 580)) : value); }, [playing, playhead, maxPan]);
  const seek = (seconds: number) => { const bounded = Math.max(0, Math.min(durationSeconds, seconds)); if (audio.current) audio.current.currentTime = bounded; setTime(bounded); }; const select = (segment: EditorSegment) => { setSelectedId(segment.id); seek(segment.startMs / 1000); };
  const toggle = async () => { if (!audio.current) return; try { if (audio.current.paused) await audio.current.play(); else audio.current.pause(); } catch { toast.error("Audio preview could not start. Your saved Timeline is unchanged."); } };
  const startResize = (event: React.PointerEvent<HTMLSpanElement>, segment: EditorSegment, edge: "start" | "end") => { if (savingTiming) return; event.preventDefault(); event.stopPropagation(); event.currentTarget.setPointerCapture(event.pointerId); const original = edge === "start" ? segment.startMs : segment.endMs; setGesture({ id: segment.id, edge, clientX: event.clientX, original }); setDraft(original); };
  const updateResize = (event: React.PointerEvent<HTMLDivElement>) => { if (!gesture || savingTiming) return; const candidate = Math.round((gesture.original + ((event.clientX - gesture.clientX) / pps) * 1000) / 100) * 100; if (canPreviewBoundary(segments, gesture.id, gesture.edge, candidate)) setDraft(candidate); };
  const finishResize = () => { if (gesture && draft !== null && draft !== gesture.original) onAdjustBoundary({ segmentId: gesture.id, edge: gesture.edge, boundaryMs: draft }); setGesture(null); setDraft(null); };
  const nudge = (edge: "start" | "end", seconds: number) => { if (!selected) return; const boundary = (edge === "start" ? selected.startMs : selected.endMs) + seconds * 1000; if (canPreviewBoundary(display, selected.id, edge, boundary)) onAdjustBoundary({ segmentId: selected.id, edge, boundaryMs: boundary }); else toast.error("Both neighboring clips must remain at least one second long."); };
  return <section className="overflow-hidden rounded-2xl border border-white/[0.08] bg-[#070b13] shadow-[0_22px_90px_rgba(0,0,0,.28)]"><div className="grid lg:grid-cols-[minmax(0,1fr)_292px]"><main className="min-w-0 border-b border-white/[0.08] lg:border-b-0 lg:border-r"><div className="flex items-center justify-between border-b border-white/[0.07] bg-[#0c1420] px-4 py-3"><div className="flex items-center gap-2"><MonitorPlay className="h-4 w-4 text-cyan-200" /><p className="text-xs font-semibold text-slate-100">{projectName}</p><span className="hidden text-[10px] text-slate-500 sm:inline">· visual editor</span></div><div className="font-mono text-[10px]"><span className="rounded bg-black/20 px-2 py-1 text-amber-100">{formatTime(time * 1000)}</span><span className="mx-1 text-slate-600">/</span><span className="text-slate-400">{formatTime(durationMs)}</span></div></div><div className="p-4"><div className="relative aspect-video overflow-hidden rounded-xl border border-white/[0.1] bg-black shadow-[0_12px_28px_rgba(0,0,0,.35)]">{current ? <StorageThumbnail src={current.thumbnailUrl} alt={current.imageFilename ?? "Current visual"} className="h-full w-full object-contain" /> : null}<div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/90 via-black/35 to-transparent px-4 pb-3 pt-14"><div className="flex items-end justify-between gap-3"><div className="min-w-0"><p className="truncate text-xs font-semibold text-white">{current?.imageFilename ?? "Current visual"}</p><p className="mt-1 line-clamp-1 text-[11px] text-slate-300">{current?.narrationText ?? "Timeline narration"}</p></div><Badge className="border border-violet-100/20 bg-violet-100/10 text-[9px] text-violet-50">{renderTransition === "Crossfade" ? `CROSSFADE ${formatSeconds(visualSettings.crossfadeDurationMs)}` : "DIRECT CUT"}</Badge></div></div></div><div className="mt-3 flex items-center gap-3 rounded-xl border border-white/[0.08] bg-[#0d1521] px-3 py-2"><Button size="icon" onClick={toggle} disabled={!narrationUrl} className="h-9 w-9 rounded-lg bg-amber-300 text-slate-950 hover:bg-amber-200">{playing ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}</Button><div className="min-w-0 flex-1"><input aria-label="Timeline preview position" type="range" min="0" max={durationSeconds} step="0.01" value={time} onChange={event => seek(Number(event.target.value))} className="h-1.5 w-full cursor-pointer accent-amber-300" /><p className="mt-1 font-mono text-[10px] text-slate-500">Now showing image {clipIndex + 1} / {segments.length}</p></div><Maximize2 className="h-4 w-4 text-slate-500" /></div><audio ref={audio} src={narrationUrl ?? undefined} onTimeUpdate={event => setTime(event.currentTarget.currentTime)} onPlay={() => setPlaying(true)} onPause={() => setPlaying(false)} onEnded={() => setPlaying(false)} /></div></main><aside className="bg-[#0b111c] p-3"><ExportPanel approved={approved} approving={approving} segments={display} durationMs={durationMs} onApprove={onApprove} /><SceneFadePanel visualSettings={visualSettings} /><TransitionPanel choice={choice} activeRenderTransition={renderTransition} durationMs={visualSettings.crossfadeDurationMs} onChoose={next => { setChoice(next); if (next !== renderTransition) toast.message(`${next} is Timeline UI-only. Render output remains ${renderTransition}.`); }} /><section className="rounded-xl border border-white/[0.08] bg-[#101824] p-3"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">Selected clip</p>{selected ? <><p className="mt-2 truncate text-xs font-semibold text-slate-100">{selected.imageFilename ?? "Selected visual"}</p><p className="mt-1 font-mono text-[10px] text-cyan-100">{formatTime(selected.startMs)} — {formatTime(selected.endMs)}</p><div className="mt-3 grid grid-cols-2 gap-1.5"><Button size="sm" variant="outline" disabled={savingTiming} onClick={() => nudge("start", -0.5)} className="border-white/10 text-[10px] text-slate-300">← Extend</Button><Button size="sm" variant="outline" disabled={savingTiming} onClick={() => nudge("end", 0.5)} className="border-white/10 text-[10px] text-slate-300">Extend →</Button></div><Button size="sm" variant="outline" onClick={() => onReplace(selected)} className="mt-2 w-full border-white/10 text-[10px] text-slate-300">Choose another image</Button></> : null}</section></aside></div><div className="border-t border-white/[0.08] bg-[#080d16] p-3 sm:p-4"><div className="mb-2 flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[.14em] text-slate-500"><span className="text-cyan-100">V · visual clips</span><span className="text-emerald-100">A · narration timing</span><span className="text-violet-200">◇ {renderTransition}</span></div><div className="flex items-center gap-1 rounded-lg border border-white/[0.08] bg-white/[0.03] p-1"><Button size="icon" variant="ghost" aria-label="Pan left" onClick={() => setPan(value => Math.max(0, value - 360))} className="h-7 w-7 text-slate-400"><ChevronLeft className="h-4 w-4" /></Button><Button size="icon" variant="ghost" aria-label="Zoom out" onClick={() => setZoom(value => Math.max(0.35, Number((value - 0.15).toFixed(2))))} className="h-7 w-7 text-slate-400"><Minus className="h-3.5 w-3.5" /></Button><span className="w-9 text-center font-mono text-[10px] text-cyan-100">{zoom}x</span><Button size="icon" variant="ghost" aria-label="Zoom in" onClick={() => setZoom(value => Math.min(4, Number((value + 0.15).toFixed(2))))} className="h-7 w-7 text-slate-400"><Plus className="h-3.5 w-3.5" /></Button><Button size="icon" variant="ghost" aria-label="Pan right" onClick={() => setPan(value => Math.min(maxPan, value + 360))} className="h-7 w-7 text-slate-400"><ChevronRight className="h-4 w-4" /></Button></div></div><p className="mb-3 text-[10px] text-slate-500">Drag a visual clip onto another clip to swap their positions. Drag cyan clip-edge handles to resize timing; the neighboring clip follows so narration coverage remains continuous.</p><div onPointerMove={updateResize} onPointerUp={finishResize} onPointerCancel={finishResize} className="relative h-[174px] overflow-hidden rounded-xl border border-white/[0.08] bg-[#090f19]" aria-label="Integrated editable visual and narration timeline"><div className="absolute inset-y-0 left-0 transition-transform duration-200 ease-out" style={{ width: trackWidth, transform: `translateX(${-pan}px)` }}><div className="relative h-9 border-b border-white/[0.08] bg-[#111a28]">{ticks.map(tick => <div key={tick} className="absolute top-0 h-full border-l border-white/[0.12]" style={{ left: (tick / 1000) * pps }}><span className="absolute left-1 top-2 font-mono text-[9px] text-slate-500">{formatTime(tick)}</span></div>)}</div><div className="relative h-[90px] border-b border-white/[0.08] bg-[linear-gradient(90deg,rgba(255,255,255,.022)_1px,transparent_1px)] bg-[size:30px_100%]"><span className="absolute left-2 top-2 z-30 rounded bg-black/65 px-1.5 py-0.5 text-[8px] font-semibold text-cyan-100">V</span>{display.map((segment, index) => <button type="button" key={segment.id} draggable={!savingTiming} onDragStart={() => setDraggedId(segment.id)} onDragEnd={() => setDraggedId(null)} onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); if (draggedId && draggedId !== segment.id) onMoveVisual(draggedId, segment.id); setDraggedId(null); }} onClick={() => select(segment)} title={`Clip ${index + 1}: ${timelineDecisionEvidence(segment.selectionReason)}`} className={`group absolute top-6 h-[70px] overflow-visible rounded-md border text-left shadow-lg transition-[left,width,transform,border-color,box-shadow] duration-150 ${selected?.id === segment.id ? "z-20 border-amber-200 ring-2 ring-amber-300/40" : "border-white/15 hover:z-20 hover:-translate-y-0.5 hover:border-cyan-100/70"}`} style={{ left: (segment.startMs / 1000) * pps, width: Math.max(42, ((segment.endMs - segment.startMs) / 1000) * pps) }}><StorageThumbnail src={segment.thumbnailUrl} alt={segment.imageFilename ?? `Visual clip ${index + 1}`} className="h-full w-full rounded-[5px] object-cover" /><span className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/95 via-black/50 to-transparent px-1.5 pb-1 pt-6"><span className="block truncate font-mono text-[9px] text-white">{formatSeconds(segment.endMs - segment.startMs)}</span></span>{index > 0 && renderTransition === "Crossfade" ? <span className="absolute -left-2 top-[27px] z-30 grid h-4 w-4 rotate-45 place-items-center rounded-[3px] border border-violet-100/70 bg-violet-300 shadow-[0_0_0_2px_rgba(6,11,20,.85)]"><GitCommitHorizontal className="h-2.5 w-2.5 -rotate-45 text-slate-950" /></span> : null}{index > 0 ? <span role="separator" aria-label="Resize start boundary" onPointerDown={event => startResize(event, segment, "start")} className="absolute -left-1 top-1 z-40 h-[66px] w-2 cursor-col-resize rounded bg-cyan-200/0 transition hover:bg-cyan-200/75" /> : null}{index < display.length - 1 ? <span role="separator" aria-label="Resize end boundary" onPointerDown={event => startResize(event, segment, "end")} className="absolute -right-1 top-1 z-40 h-[66px] w-2 cursor-col-resize rounded bg-cyan-200/0 transition hover:bg-cyan-200/75" /> : null}</button>)}</div><div className="relative h-[45px] bg-[#07140f]"><span className="absolute left-2 top-3 z-30 rounded bg-black/55 px-1.5 py-0.5 text-[8px] font-semibold text-emerald-100">A</span>{display.map(segment => <button type="button" key={`audio-${segment.id}`} onClick={() => select(segment)} aria-label={`Seek narration to ${formatTime(segment.startMs)}`} className="absolute top-3 h-5 overflow-hidden rounded-sm border border-emerald-100/20 bg-emerald-300/30 transition hover:bg-emerald-200/50" style={{ left: (segment.startMs / 1000) * pps, width: Math.max(5, ((segment.endMs - segment.startMs) / 1000) * pps - 1) }}><span className="absolute inset-0" style={{ backgroundImage: "repeating-linear-gradient(90deg,transparent 0 3px,rgba(167,243,208,.9) 3px 5px,transparent 5px 8px)" }} /></button>)}</div><div aria-hidden="true" className="pointer-events-none absolute bottom-0 top-0 z-40 w-px bg-amber-300 shadow-[0_0_0_1px_rgba(251,191,36,.18),0_0_12px_rgba(251,191,36,.75)]" style={{ left: playhead }}><span className="absolute -left-[4px] -top-1 h-2 w-2 rotate-45 bg-amber-300" /></div></div></div></div></section>;
}

function EditorTimeline({ narrationUrl, segments, projectName, visualSettings, approved, approving, savingTiming, onApprove, onReplace, onAdjustBoundary, onMoveVisual }: { narrationUrl: string | null; segments: EditorSegment[]; projectName: string; visualSettings: VisualSettings; approved: boolean; approving: boolean; savingTiming: boolean; onApprove: () => void; onReplace: (segment: ReplaceTarget) => void; onAdjustBoundary: (change: { segmentId: number; edge: "start" | "end"; boundaryMs: number }) => void; onMoveVisual: (sourceSegmentId: number, targetSegmentId: number) => void }) {
  const audio = useRef<HTMLAudioElement>(null);
  const viewport = useRef<HTMLDivElement>(null);
  const [time, setTime] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [viewScale, setViewScale] = useState(0.6);
  const [selectedId, setSelectedId] = useState<number>(segments[0]?.id ?? 0);
  const [transitionChoice, setTransitionChoice] = useState<TransitionChoice>(visualSettings.crossfadeDurationMs > 0 ? "Crossfade" : "None");
  const [draggedVisualId, setDraggedVisualId] = useState<number | null>(null);
  const [resizeGesture, setResizeGesture] = useState<{ segmentId: number; edge: "start" | "end"; startX: number; originBoundaryMs: number } | null>(null);
  const [draftBoundaryMs, setDraftBoundaryMs] = useState<number | null>(null);
  const durationMs = Math.max(1, segments.at(-1)?.endMs ?? 1);
  const durationSeconds = durationMs / 1000;
  const innerWidth = Math.max(760, durationSeconds * viewScale);
  const matchingIndex = segments.findIndex(segment => time * 1000 >= segment.startMs && time * 1000 < segment.endMs);
  const currentIndex = matchingIndex >= 0 ? matchingIndex : Math.max(0, segments.length - 1);
  const displaySegments = useMemo(() => previewBoundaryAdjustment(segments, resizeGesture?.segmentId ?? null, resizeGesture?.edge ?? null, draftBoundaryMs), [segments, resizeGesture, draftBoundaryMs]);
  const current = displaySegments[currentIndex] ?? displaySegments[0];
  const selected = displaySegments.find(segment => segment.id === selectedId) ?? current;
  const rulerTicks = useMemo(() => buildRulerTicks(durationMs), [durationMs]);
  const playheadLeft = Math.min(innerWidth, Math.max(0, time * viewScale));
  const activeRenderTransition = visualSettings.crossfadeDurationMs > 0 ? "Crossfade" : "None";

  useEffect(() => { setSelectedId(segments[0]?.id ?? 0); setTime(0); setResizeGesture(null); setDraftBoundaryMs(null); }, [segments]);
  useEffect(() => { if (playing && viewport.current) { const view = viewport.current; if (playheadLeft < view.scrollLeft + 48 || playheadLeft > view.scrollLeft + view.clientWidth - 64) view.scrollTo({ left: Math.max(0, playheadLeft - view.clientWidth * 0.45), behavior: "smooth" }); } }, [playheadLeft, playing]);
  const seek = (seconds: number) => { const bounded = Math.max(0, Math.min(durationSeconds, seconds)); if (audio.current) audio.current.currentTime = bounded; setTime(bounded); };
  const selectClip = (segment: EditorSegment) => { setSelectedId(segment.id); seek(segment.startMs / 1000); };
  const toggle = async () => { if (!audio.current) return; try { if (audio.current.paused) await audio.current.play(); else audio.current.pause(); } catch { toast.error("Audio preview could not start. Your saved Timeline is unchanged."); } };
  const moveSelection = (offset: number) => { const index = Math.max(0, Math.min(segments.length - 1, segments.findIndex(segment => segment.id === selected?.id) + offset)); selectClip(segments[index]); };
  const chooseTransition = (choice: TransitionChoice) => { setTransitionChoice(choice); if (choice !== activeRenderTransition) toast.message(`${choice} is included as a Timeline editor option only. Render output remains ${activeRenderTransition}.`); };
  const beginResize = (event: React.PointerEvent<HTMLSpanElement>, segment: EditorSegment, edge: "start" | "end") => { if (savingTiming) return; event.preventDefault(); event.stopPropagation(); event.currentTarget.setPointerCapture(event.pointerId); setResizeGesture({ segmentId: segment.id, edge, startX: event.clientX, originBoundaryMs: edge === "start" ? segment.startMs : segment.endMs }); setDraftBoundaryMs(edge === "start" ? segment.startMs : segment.endMs); };
  const updateResize = (event: React.PointerEvent<HTMLDivElement>) => { if (!resizeGesture || savingTiming) return; const nextBoundary = Math.round((resizeGesture.originBoundaryMs + ((event.clientX - resizeGesture.startX) / viewScale) * 1000) / 100) * 100; if (canPreviewBoundary(segments, resizeGesture.segmentId, resizeGesture.edge, nextBoundary)) setDraftBoundaryMs(nextBoundary); };
  const finishResize = () => { if (!resizeGesture) return; if (draftBoundaryMs !== null && draftBoundaryMs !== resizeGesture.originBoundaryMs) onAdjustBoundary({ segmentId: resizeGesture.segmentId, edge: resizeGesture.edge, boundaryMs: draftBoundaryMs }); setResizeGesture(null); setDraftBoundaryMs(null); };

  return <section className="overflow-hidden rounded-2xl border border-white/[0.08] bg-[#070b13] shadow-[0_22px_90px_rgba(0,0,0,.28)]">
    <div className="grid lg:grid-cols-[minmax(0,1fr)_292px]">
      <main className="min-w-0 border-b border-white/[0.08] lg:border-b-0 lg:border-r">
        <div className="border-b border-white/[0.07] bg-[#0c1420] px-4 py-3"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-2"><MonitorPlay className="h-4 w-4 text-cyan-200" /><p className="text-xs font-semibold text-slate-100">{projectName}</p><span className="text-[10px] text-slate-500">· visual review preview</span></div><div className="flex items-center gap-2 font-mono text-[10px]"><span className="rounded-md border border-white/[0.08] bg-black/20 px-2 py-1 text-amber-100">{formatTime(time * 1000)}</span><span className="text-slate-600">/</span><span className="text-slate-400">{formatTime(durationMs)}</span><span className="ml-1 rounded-md border border-white/[0.08] bg-white/[0.03] px-2 py-1 text-slate-400">Image {currentIndex + 1} / {segments.length}</span></div></div></div>
        <div className="p-4"><div className="relative aspect-video overflow-hidden rounded-xl border border-white/[0.1] bg-black shadow-[0_12px_28px_rgba(0,0,0,.35)]">{current ? <StorageThumbnail src={current.thumbnailUrl} alt={current.imageFilename ?? "Current timeline image"} className="h-full w-full object-contain" /> : null}<div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent px-4 pb-3 pt-14"><div className="flex items-end justify-between gap-3"><div className="min-w-0"><p className="truncate text-xs font-semibold text-white">{current?.imageFilename ?? "Current visual"}</p><p className="mt-1 line-clamp-1 text-[11px] text-slate-300">{current?.narrationText ?? "Timeline narration"}</p></div><div className="flex gap-1">{visualSettings.enabled ? <Badge className="border border-cyan-100/20 bg-cyan-100/10 text-[9px] text-cyan-50 hover:bg-cyan-100/10"><ZoomIn className="mr-1 h-3 w-3" />{resolvedZoomDirection(visualSettings, currentIndex)}</Badge> : null}<Badge className="border border-violet-100/20 bg-violet-100/10 text-[9px] text-violet-50 hover:bg-violet-100/10">{activeRenderTransition === "Crossfade" ? `CROSSFADE ${formatSeconds(visualSettings.crossfadeDurationMs)}` : "DIRECT CUT"}</Badge></div></div></div></div>
          <div className="mt-3 flex items-center gap-3 rounded-xl border border-white/[0.08] bg-[#0d1521] px-3 py-2.5"><Button size="icon" onClick={toggle} disabled={!narrationUrl} className="h-9 w-9 rounded-lg bg-amber-300 text-slate-950 hover:bg-amber-200 disabled:opacity-50">{playing ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}</Button><div className="min-w-0 flex-1"><input aria-label="Timeline preview position" type="range" min="0" max={durationSeconds} step="0.01" value={time} onChange={event => seek(Number(event.target.value))} className="h-1.5 w-full cursor-pointer accent-amber-300" /><div className="mt-1 flex justify-between font-mono text-[10px] text-slate-500"><span>{formatTime(time * 1000)}</span><span>{formatTime(durationMs)}</span></div></div><button type="button" aria-label="Preview workspace size" className="grid h-8 w-8 place-items-center rounded-md text-slate-500 transition hover:bg-white/[0.06] hover:text-slate-200"><Maximize2 className="h-4 w-4" /></button></div>
          <audio ref={audio} src={narrationUrl ?? undefined} onTimeUpdate={event => setTime(event.currentTarget.currentTime)} onPlay={() => setPlaying(true)} onPause={() => setPlaying(false)} onEnded={() => setPlaying(false)} />
        </div>
      </main>
      <aside className="min-w-0 bg-[#0b111c] p-3">
        <ExportPanel approved={approved} approving={approving} segments={segments} durationMs={durationMs} onApprove={onApprove} />
        <SceneFadePanel visualSettings={visualSettings} />
        <TransitionPanel choice={transitionChoice} activeRenderTransition={activeRenderTransition} durationMs={visualSettings.crossfadeDurationMs} onChoose={chooseTransition} />
        <section className="rounded-xl border border-white/[0.08] bg-[#101824] p-3"><div className="flex items-center gap-2"><FileText className="h-3.5 w-3.5 text-cyan-200" /><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">Narration</p></div><p className="mt-2 text-xs leading-5 text-slate-400">Original narration remains the timing source. Clip selection, preview seeking, and editor choices do not rewrite captions or timing.</p></section>
      </aside>
      <TimelineClipEditor className="lg:col-span-2" segments={displaySegments} selected={selected} saving={savingTiming} draggedVisualId={draggedVisualId} onDragVisual={setDraggedVisualId} onSelect={selectClip} onAdjustBoundary={onAdjustBoundary} onMoveVisual={onMoveVisual} />
    </div>
    <div className="border-t border-white/[0.08] bg-[#080d16] p-3 sm:p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[.14em] text-slate-500"><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-sm bg-cyan-300" />Visuals</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-sm bg-emerald-300" />Narration</span><span className="flex items-center gap-1.5"><GitCommitHorizontal className="h-3 w-3 text-violet-200" />{activeRenderTransition} markers</span></div><div className="flex items-center gap-2 rounded-lg border border-white/[0.08] bg-white/[0.03] px-2 py-1"><span className="text-[10px] text-slate-500">Timeline view</span><Button variant="ghost" size="icon" aria-label="Zoom out timeline view" onClick={() => setViewScale(value => Math.max(0.25, Number((value - 0.25).toFixed(2))))} className="h-6 w-6 text-slate-400 hover:bg-white/[0.08] hover:text-white"><Minus className="h-3.5 w-3.5" /></Button><span className="w-9 text-center font-mono text-[10px] text-cyan-100">{viewScale}x</span><Button variant="ghost" size="icon" aria-label="Zoom in timeline view" onClick={() => setViewScale(value => Math.min(6, Number((value + 0.25).toFixed(2))))} className="h-6 w-6 text-slate-400 hover:bg-white/[0.08] hover:text-white"><Plus className="h-3.5 w-3.5" /></Button></div></div>
      <div ref={viewport} className="relative overflow-x-auto overscroll-x-contain rounded-lg border border-white/[0.08] bg-[#090f19] pb-3" aria-label="Visual sequence timeline"><div className="relative" style={{ width: innerWidth }}><div className="relative h-8 border-b border-white/[0.08] bg-[#101824]">{rulerTicks.map(tick => <div key={tick} className="absolute top-0 h-full border-l border-white/[0.12]" style={{ left: (tick / 1000) * viewScale }}><span className="absolute left-1 top-2 font-mono text-[9px] text-slate-500">{formatTime(tick)}</span></div>)}</div><div className="relative h-[112px] border-b border-white/[0.08] bg-[linear-gradient(90deg,rgba(255,255,255,.025)_1px,transparent_1px)] bg-[size:28px_100%]"><div className="absolute left-2 top-2 z-20 rounded bg-black/55 px-1.5 py-0.5 text-[8px] font-semibold uppercase tracking-[.14em] text-slate-400">V</div>{segments.map((segment, index) => <button type="button" key={segment.id} onClick={() => selectClip(segment)} onFocus={() => setSelectedId(segment.id)} title={`Clip ${index + 1}: ${formatTime(segment.startMs)}–${formatTime(segment.endMs)} · ${formatSeconds(segment.endMs - segment.startMs)} · ${timelineDecisionEvidence(segment.selectionReason)}`} className={`group absolute top-6 h-[78px] overflow-visible rounded-md border text-left shadow-lg transition-[transform,border-color,box-shadow] duration-150 focus:outline-none ${selected?.id === segment.id ? "z-10 border-amber-200 ring-2 ring-amber-300/40" : "border-white/15 hover:z-10 hover:-translate-y-0.5 hover:border-cyan-100/70 hover:shadow-cyan-500/15"}`} style={{ left: (segment.startMs / 1000) * viewScale, width: Math.max(40, ((segment.endMs - segment.startMs) / 1000) * viewScale) }}><StorageThumbnail src={segment.thumbnailUrl} alt={segment.imageFilename ?? `Timeline clip ${index + 1}`} className="h-full w-full rounded-[5px] object-cover opacity-90 transition-opacity group-hover:opacity-100" /><span className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/95 via-black/50 to-transparent px-1.5 pb-1 pt-6"><span className="block truncate font-mono text-[9px] text-white">{formatSeconds(segment.endMs - segment.startMs)}</span></span>{visualSettings.enabled ? <span className="absolute right-1 top-1 grid h-4 w-4 place-items-center rounded bg-cyan-300 text-slate-950 shadow"><ZoomIn className="h-2.5 w-2.5" /></span> : null}{activeRenderTransition === "Crossfade" && index > 0 ? <span title={`Crossfade · ${formatSeconds(visualSettings.crossfadeDurationMs)}`} className="absolute -left-2 top-[31px] z-20 grid h-4 w-4 place-items-center rotate-45 rounded-[3px] border border-violet-100/70 bg-violet-300 shadow-[0_0_0_2px_rgba(6,11,20,.85)]"><GitCommitHorizontal className="h-2.5 w-2.5 -rotate-45 text-slate-950" /></span> : null}</button>)}</div><div className="relative h-11 bg-[#07140f]"><div className="absolute left-2 top-3 z-20 rounded bg-black/45 px-1.5 py-0.5 text-[8px] font-semibold uppercase tracking-[.14em] text-emerald-100">A</div>{segments.map(segment => <button type="button" key={`audio-${segment.id}`} aria-label={`Seek narration to ${formatTime(segment.startMs)}`} onClick={() => selectClip(segment)} className="absolute top-3 h-5 rounded-sm border border-emerald-100/15 bg-emerald-300/35 transition hover:bg-emerald-200/55 focus:outline-none focus:ring-2 focus:ring-emerald-200/70" style={{ left: (segment.startMs / 1000) * viewScale, width: Math.max(4, ((segment.endMs - segment.startMs) / 1000) * viewScale - 1) }} />)}</div><div aria-hidden="true" className="pointer-events-none absolute bottom-0 top-0 z-30 w-px bg-amber-300 shadow-[0_0_0_1px_rgba(251,191,36,.18),0_0_12px_rgba(251,191,36,.75)]" style={{ left: playheadLeft }}><span className="absolute -left-[4px] -top-1 h-2 w-2 rotate-45 bg-amber-300" /></div></div></div>
      <p className="mt-2 px-1 text-[10px] leading-4 text-slate-500">The editor uses the saved clip boundaries and narration coverage exactly as generated. Timeline view zoom, clip selection, preview seeking, and non-crossfade transition choices affect only this Timeline interface.</p>
    </div>
  </section>;
}

function TimelineClipEditor({ className, segments, selected, saving, draggedVisualId, onDragVisual, onSelect, onAdjustBoundary, onMoveVisual }: { className?: string; segments: EditorSegment[]; selected: EditorSegment | undefined; saving: boolean; draggedVisualId: number | null; onDragVisual: (id: number | null) => void; onSelect: (segment: EditorSegment) => void; onAdjustBoundary: (change: { segmentId: number; edge: "start" | "end"; boundaryMs: number }) => void; onMoveVisual: (sourceSegmentId: number, targetSegmentId: number) => void }) {
  const selectedIndex = segments.findIndex(segment => segment.id === selected?.id);
  const previous = selectedIndex > 0 ? segments[selectedIndex - 1] : null;
  const next = selectedIndex >= 0 && selectedIndex < segments.length - 1 ? segments[selectedIndex + 1] : null;
  const commitBoundary = (edge: "start" | "end", rawValue: string) => { const boundaryMs = Math.round(Number(rawValue) * 1000); if (!selected || !Number.isFinite(boundaryMs)) { toast.error("Enter a valid time in seconds."); return; } onAdjustBoundary({ segmentId: selected.id, edge, boundaryMs }); };
  return <section className={`${className ?? ""} border-t border-white/[0.08] bg-[#0a101a] p-3 sm:p-4`}><div className="flex flex-col gap-3 xl:flex-row xl:items-start"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-cyan-100">Clip editor</p><p className="mt-1 text-xs text-slate-500">Drag a visual card onto another clip to swap their positions. Edit a boundary to resize two neighboring clips without creating a narration gap.</p></div>{saving ? <Badge className="border border-amber-200/15 bg-amber-200/[0.08] text-amber-100 hover:bg-amber-200/[0.08]">Saving edit…</Badge> : <Badge className="border border-white/[0.08] bg-white/[0.04] text-slate-400 hover:bg-white/[0.04]">Timing locked to narration</Badge>}</div><div className="mt-3 flex gap-2 overflow-x-auto pb-1">{segments.map((segment, index) => <button type="button" key={`clip-editor-${segment.id}`} draggable={!saving} onDragStart={() => onDragVisual(segment.id)} onDragEnd={() => onDragVisual(null)} onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); if (draggedVisualId && draggedVisualId !== segment.id) onMoveVisual(draggedVisualId, segment.id); onDragVisual(null); }} onClick={() => onSelect(segment)} className={`group relative w-28 shrink-0 overflow-hidden rounded-lg border text-left transition ${selected?.id === segment.id ? "border-amber-300 ring-2 ring-amber-300/30" : "border-white/[0.09] hover:border-cyan-200/60"}`}><div className="aspect-video bg-black"><StorageThumbnail src={segment.thumbnailUrl} alt={segment.imageFilename ?? `Clip ${index + 1}`} className="h-full w-full object-cover" /></div><div className="bg-[#111a27] px-2 py-1.5"><p className="truncate font-mono text-[9px] text-slate-200">{formatTime(segment.startMs)}</p><p className="mt-0.5 truncate text-[9px] text-slate-500">{formatSeconds(segment.endMs - segment.startMs)}</p></div><span className="absolute right-1 top-1 rounded bg-black/70 px-1 py-0.5 text-[8px] font-semibold text-white">{index + 1}</span></button>)}</div></div>
    <div className="w-full shrink-0 rounded-xl border border-white/[0.08] bg-[#101824] p-3 xl:w-[310px]"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">Selected clip timing</p>{selected ? <><p className="mt-2 truncate text-xs font-semibold text-slate-100">{selected.imageFilename ?? "Selected visual"}</p><p className="mt-1 text-[10px] leading-4 text-slate-500">Changing a boundary changes only this clip and its direct neighbor. Both must stay at least one second long.</p><div className="mt-3 grid grid-cols-2 gap-2"><label className="text-[10px] text-slate-500">Start (sec)<input aria-label="Selected clip start seconds" disabled={!previous || saving} defaultValue={(selected.startMs / 1000).toFixed(1)} key={`start-${selected.id}-${selected.startMs}`} type="number" step="0.1" min={(previous ? (previous.startMs + 1000) / 1000 : 0).toFixed(1)} max={((selected.endMs - 1000) / 1000).toFixed(1)} onBlur={event => commitBoundary("start", event.currentTarget.value)} className="mt-1 h-8 w-full rounded-md border border-white/[0.09] bg-black/20 px-2 font-mono text-xs text-cyan-100 outline-none focus:border-cyan-200/60 disabled:cursor-not-allowed disabled:opacity-40" /></label><label className="text-[10px] text-slate-500">End (sec)<input aria-label="Selected clip end seconds" disabled={!next || saving} defaultValue={(selected.endMs / 1000).toFixed(1)} key={`end-${selected.id}-${selected.endMs}`} type="number" step="0.1" min={((selected.startMs + 1000) / 1000).toFixed(1)} max={(next ? (next.endMs - 1000) / 1000 : selected.endMs / 1000).toFixed(1)} onBlur={event => commitBoundary("end", event.currentTarget.value)} className="mt-1 h-8 w-full rounded-md border border-white/[0.09] bg-black/20 px-2 font-mono text-xs text-cyan-100 outline-none focus:border-cyan-200/60 disabled:cursor-not-allowed disabled:opacity-40" /></label></div><div className="mt-3 flex gap-2"><Button variant="outline" size="sm" disabled={!previous || saving} onClick={() => onSelect(previous!)} className="flex-1 border-white/10 text-slate-300 hover:bg-white/[0.06]"><ChevronLeft className="mr-1 h-3.5 w-3.5" />Previous</Button><Button variant="outline" size="sm" disabled={!next || saving} onClick={() => onSelect(next!)} className="flex-1 border-white/10 text-slate-300 hover:bg-white/[0.06]">Next<ChevronRight className="ml-1 h-3.5 w-3.5" /></Button></div></> : <p className="mt-3 text-xs text-slate-500">Select a visual clip to edit its timing.</p>}</div>
  </div></section>;
}
function ExportPanel({ approved, approving, segments, durationMs, onApprove }: { approved: boolean; approving: boolean; segments: EditorSegment[]; durationMs: number; onApprove: () => void }) { return <section className="mb-3 rounded-xl border border-white/[0.08] bg-[#101824] p-3"><div className="flex items-center gap-2"><Clapperboard className="h-3.5 w-3.5 text-cyan-200" /><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">Export</p></div><div className="mt-3 grid grid-cols-2 gap-2"><Readout label="Aspect" value="16:9 · 1920" /><Readout label="FPS" value="30 fps" /></div><dl className="mt-3 space-y-2 border-t border-white/[0.07] pt-3 text-xs"><div className="flex justify-between gap-3"><dt className="text-slate-500">Resolution</dt><dd className="font-mono text-slate-200">1920×1080</dd></div><div className="flex justify-between gap-3"><dt className="text-slate-500">Images</dt><dd className="font-mono text-slate-200">{segments.length}</dd></div><div className="flex justify-between gap-3"><dt className="text-slate-500">Length</dt><dd className="font-mono text-slate-200">{formatTime(durationMs)}</dd></div></dl>{approved ? <div className="mt-3 flex items-center justify-center gap-2 rounded-lg border border-emerald-200/15 bg-emerald-200/[0.08] px-3 py-2 text-xs font-semibold text-emerald-100"><CircleCheckBig className="h-4 w-4" />Timeline approved</div> : <Button onClick={onApprove} disabled={approving} className="mt-3 h-10 w-full bg-[#5578ff] text-white hover:bg-[#6887ff]">{approving ? "Approving…" : "Approve Timeline"}</Button>}<p className="mt-2 text-center text-[10px] leading-4 text-slate-500">Approval unlocks the existing local render handoff. It never starts a render.</p></section>; }
function Readout({ label, value }: { label: string; value: string }) { return <div className="rounded-lg border border-white/[0.07] bg-black/20 p-2"><p className="text-[9px] uppercase tracking-[.13em] text-slate-500">{label}</p><p className="mt-1 font-mono text-[11px] text-slate-200">{value}</p></div>; }
function SceneFadePanel({ visualSettings }: { visualSettings: VisualSettings }) { const duration = visualSettings.crossfadeDurationMs; return <section className="mb-3 rounded-xl border border-white/[0.08] bg-[#101824] p-3"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">Scene fades</p><p className="mt-2 text-[11px] leading-5 text-slate-500">Saved motion settings are read-only here. Change them only in Preview.</p><div className="mt-3 space-y-2"><FadeReadout label="Crossfade" value={duration > 0 ? formatSeconds(duration) : "Off"} progress={Math.min(100, duration / 12)} active={duration > 0} /><FadeReadout label="Zoom" value={visualSettings.enabled ? `${visualSettings.amountPercent}% · ${visualSettings.direction}` : "Off"} progress={visualSettings.enabled ? visualSettings.amountPercent * 7 : 0} active={visualSettings.enabled} /></div></section>; }
function FadeReadout({ label, value, progress, active }: { label: string; value: string; progress: number; active: boolean }) { return <div><div className="mb-1 flex justify-between text-[10px]"><span className="text-slate-500">{label}</span><span className={active ? "text-cyan-100" : "text-slate-500"}>{value}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-black/30"><div className={active ? "h-full rounded-full bg-cyan-300" : "h-full rounded-full bg-slate-600"} style={{ width: `${progress}%` }} /></div></div>; }
function TransitionPanel({ choice, activeRenderTransition, durationMs, onChoose }: { choice: TransitionChoice; activeRenderTransition: "None" | "Crossfade"; durationMs: number; onChoose: (choice: TransitionChoice) => void }) { return <section className="mb-3 rounded-xl border border-white/[0.08] bg-[#101824] p-3"><div className="flex items-center justify-between gap-2"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">Transitions</p><Badge className="border border-amber-200/15 bg-amber-200/[0.08] text-[9px] text-amber-100 hover:bg-amber-200/[0.08]">UI only</Badge></div><p className="mt-2 text-[11px] leading-5 text-slate-500">Choose a style to plan the edit. Only <span className="font-medium text-violet-100">{activeRenderTransition}</span> is currently applied in the validated render pipeline.</p><div className="mt-3 grid grid-cols-2 gap-1.5">{transitionChoices.map(item => <button type="button" key={item} onClick={() => onChoose(item)} className={`rounded-md border px-2 py-1.5 text-left text-[10px] transition ${choice === item ? "border-violet-200/60 bg-violet-200/15 text-violet-50" : "border-white/[0.08] bg-black/15 text-slate-400 hover:border-white/20 hover:bg-white/[0.05] hover:text-slate-200"}`}><span className="flex items-center gap-1.5">{item === "Crossfade" ? <GitCommitHorizontal className="h-3 w-3" /> : <Sparkles className="h-3 w-3 opacity-65" />}{item}</span></button>)}</div><div className="mt-3 flex items-center justify-between border-t border-white/[0.07] pt-3 text-[10px]"><span className="text-slate-500">Render transition</span><span className="font-mono text-violet-100">{activeRenderTransition === "Crossfade" ? `${formatSeconds(durationMs)} crossfade` : "direct cut"}</span></div></section>; }

function CandidateDialog({ target, candidates, loading, selectedCandidateId, pending, onClose, onSelect, onConfirm }: { target: ReplaceTarget | null; candidates: Array<{ id: number; originalFilename: string; sequenceNumber: number | null; thumbnailUrl: string; sceneDescription: string | null }>; loading: boolean; selectedCandidateId: number | null; pending: boolean; onClose: () => void; onSelect: (id: number) => void; onConfirm: () => void }) { const selected = candidates.find(candidate => candidate.id === selectedCandidateId) ?? null; return <Dialog open={Boolean(target)} onOpenChange={open => { if (!open) onClose(); }}><DialogContent className="max-h-[90vh] max-w-5xl overflow-y-auto border-white/10 bg-[#0c1422] text-slate-100"><DialogHeader><DialogTitle className="flex items-center gap-2 text-xl"><Images className="h-5 w-5 text-cyan-200" />Choose from every source image</DialogTitle><DialogDescription className="max-w-3xl text-slate-400">The complete analyzed folder library is available, including images already used elsewhere in the Timeline. Replace <span className="font-medium text-slate-200">{target?.imageFilename ?? "this selected image"}</span> for {target ? `${formatTime(target.startMs)}–${formatTime(target.endMs)}` : "this segment"}. Timing boundaries do not change.</DialogDescription></DialogHeader>{loading ? <div className="grid min-h-64 place-items-center text-sm text-slate-500">Loading analyzed alternatives…</div> : candidates.length ? <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">{candidates.map(candidate => <button type="button" key={candidate.id} onClick={() => onSelect(candidate.id)} className={`overflow-hidden rounded-xl border text-left transition ${candidate.id === selectedCandidateId ? "border-cyan-200 bg-cyan-200/[0.08] ring-2 ring-cyan-200/25" : "border-white/[0.08] bg-white/[0.025] hover:border-white/20 hover:bg-white/[0.05]"}`}><div className="aspect-video bg-[#080c15]"><StorageThumbnail src={candidate.thumbnailUrl} alt={candidate.originalFilename} className="h-full w-full object-cover" /></div><div className="p-3"><div className="flex items-center justify-between gap-2"><span className="truncate font-mono text-[10px] text-cyan-100">#{candidate.sequenceNumber ?? "—"}</span>{candidate.id === selectedCandidateId ? <CheckCheck className="h-3.5 w-3.5 text-cyan-200" /> : null}</div><p className="mt-1 truncate text-xs font-medium text-slate-100">{candidate.originalFilename}</p><p className="mt-1 line-clamp-3 text-[11px] leading-4 text-slate-500">{candidate.sceneDescription ?? "Genuine provider analysis is available; no scene description was returned."}</p></div></button>)}</div> : <div className="rounded-xl border border-dashed border-white/10 px-6 py-14 text-center text-sm text-slate-500">No analyzed images are available for this Timeline.</div>}<DialogFooter className="border-t border-white/[0.07] pt-4 sm:justify-between"><p className="hidden max-w-xl text-xs leading-5 text-amber-100/70 sm:block">Manual image substitution preserves validated narration timing but revokes approval for a fresh review.</p><div className="flex gap-2"><Button variant="outline" disabled={pending} onClick={onClose} className="border-white/10 text-slate-300 hover:bg-white/[0.06] hover:text-white">Cancel</Button><Button disabled={!selected || pending} onClick={onConfirm} className="bg-cyan-200 text-slate-950 hover:bg-cyan-100">{pending ? "Replacing…" : "Use selected image"}</Button></div></DialogFooter></DialogContent></Dialog>; }
function EmptyReview({ project, onOpenProjects, onOpenProviders }: { project?: ProjectSummary; onOpenProjects: () => void; onOpenProviders: () => void }) { const sourceDetailsMissing = project && !project.sourcesAttached; const analysisBlocked = Boolean(project?.sourcesAttached && project.analysisBlocker); return <section className="rounded-2xl border border-dashed border-white/10 bg-white/[0.018] px-6 py-14 text-center"><ShieldAlert className="mx-auto h-7 w-7 text-cyan-200" /><h2 className="mt-4 text-lg font-semibold text-white">{sourceDetailsMissing ? "Add project source details first" : analysisBlocked ? "Analysis is waiting for Groq capacity" : "No validated timeline available"}</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-slate-500">{sourceDetailsMissing ? `“${project?.name}” is still a draft. Attach real narration and image media, then build the Timeline.` : analysisBlocked ? project?.analysisBlocker : "A native handoff remains locked until genuine source media has been analyzed and a continuous Timeline has been generated and reviewed."}</p>{sourceDetailsMissing ? <Button onClick={onOpenProjects} className="mt-5 bg-cyan-200 text-slate-950 hover:bg-cyan-100">Set up project sources</Button> : analysisBlocked ? <Button onClick={onOpenProviders} className="mt-5 bg-violet-300 text-slate-950 hover:bg-violet-200">Open AI Providers</Button> : null}</section>; }
function ReviewError({ message }: { message: string }) { return <section className="rounded-2xl border border-rose-200/15 bg-rose-200/[0.045] px-6 py-10 text-center"><ShieldAlert className="mx-auto h-7 w-7 text-rose-100" /><h2 className="mt-4 text-lg font-semibold text-white">Timeline review could not be loaded</h2><p className="mx-auto mt-2 max-w-2xl text-sm leading-6 text-rose-100/70">{message}</p><p className="mx-auto mt-2 max-w-2xl text-xs leading-5 text-slate-500">Refresh the page to restore your secure session. Stored images and timing are unchanged.</p></section>; }
function canPreviewBoundary(segments: EditorSegment[], segmentId: number, edge: "start" | "end", boundaryMs: number) { const index = segments.findIndex(segment => segment.id === segmentId); const target = segments[index]; const adjacent = edge === "start" ? segments[index - 1] : segments[index + 1]; if (!target || !adjacent) return false; const lower = edge === "start" ? adjacent.startMs + 1000 : target.startMs + 1000; const upper = edge === "start" ? target.endMs - 1000 : adjacent.endMs - 1000; return Number.isInteger(boundaryMs) && boundaryMs >= lower && boundaryMs <= upper; }
function previewBoundaryAdjustment(segments: EditorSegment[], segmentId: number | null, edge: "start" | "end" | null, boundaryMs: number | null): EditorSegment[] { if (!segmentId || !edge || boundaryMs === null || !canPreviewBoundary(segments, segmentId, edge, boundaryMs)) return segments; const index = segments.findIndex(segment => segment.id === segmentId); const target = segments[index]; const adjacent = edge === "start" ? segments[index - 1] : segments[index + 1]; if (!target || !adjacent) return segments; return segments.map(segment => { if (edge === "start" && segment.id === adjacent.id) return { ...segment, endMs: boundaryMs }; if (edge === "start" && segment.id === target.id) return { ...segment, startMs: boundaryMs }; if (edge === "end" && segment.id === target.id) return { ...segment, endMs: boundaryMs }; if (edge === "end" && segment.id === adjacent.id) return { ...segment, startMs: boundaryMs }; return segment; }); }
function StorageThumbnail({ src, alt, className }: { src: string | null; alt: string; className: string }) { const [failed, setFailed] = useState(false); if (!src || failed) return <div className="grid h-full w-full place-items-center bg-[#080c15] text-slate-500" role="img" aria-label={`${alt} thumbnail unavailable`}><ImageIcon className="h-6 w-6" /></div>; return <img src={src} alt={alt} className={className} onError={() => setFailed(true)} />; }
function buildRulerTicks(durationMs: number) { const step = durationMs <= 90_000 ? 10_000 : durationMs <= 8 * 60_000 ? 30_000 : durationMs <= 30 * 60_000 ? 120_000 : 300_000; const ticks: number[] = []; for (let value = 0; value <= durationMs; value += step) ticks.push(value); if (ticks.at(-1) !== durationMs) ticks.push(durationMs); return ticks; }
function resolvedZoomDirection(settings: VisualSettings, index: number) { if (settings.direction !== "AUTO") return `ZOOM ${settings.direction}`; return `ZOOM ${index % 2 === 0 ? "IN" : "OUT"}`; }
function formatSeconds(milliseconds: number) { return `${(milliseconds / 1000).toFixed(milliseconds % 1000 === 0 ? 0 : 1)}s`; }
function formatTime(milliseconds: number) { const seconds = milliseconds / 1000; return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${(seconds % 60).toFixed(2).padStart(5, "0")}`; }
